CREATE TABLE IF NOT EXISTS authority_records (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, matter_id TEXT, name TEXT NOT NULL, citation TEXT NOT NULL, authority_type TEXT NOT NULL, court TEXT, year INTEGER, proposition TEXT, source_id TEXT, status TEXT NOT NULL DEFAULT 'UNVERIFIED', created_at TEXT NOT NULL, verified_at TEXT, payload_json TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_authority_records_scope ON authority_records(tenant_id, matter_id, citation, status);
CREATE TABLE IF NOT EXISTS authority_review_events (id INTEGER PRIMARY KEY AUTOINCREMENT, tenant_id TEXT NOT NULL, authority_id TEXT NOT NULL, reviewer TEXT NOT NULL, decision TEXT NOT NULL, notes TEXT NOT NULL, verification_source_url TEXT, verification_source_hash TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
